-- Vashj'ir spawns, part 4 of 6: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `waypoint_data` WHERE (`id` > 92601280 OR (`id` = 92601280 AND `point` >= 1)) AND (`id` < 92635370 OR (`id` = 92635370 AND `point` <= 2));





